{
  "anomaly_detected": true,
  "confidence": 0.99,
  "anomalies": [
    {
      "category": "bridged_nets",
      "components": ["FCC2", "NAVC2", "UART3_FCC2", "I2C3_NAVC2"],
      "pins": ["FCC2.48", "FCC2.73", "NAVC2.31", "NAVC2.47"],
      "nets": ["NET0019", "NET0036", "NET0124", "NET0170"],
      "observed": "The FCC STM32H753 VCAP pins 48 and 73 connect to NET0019 and NET0036, which are also the UART3_FCC2 connector signals. The NAVC STM32F405 VCAP pins 31 and 47 are assigned NET0124 and NET0170; the schematic shows no VCAP decoupling capacitors for either MCU.",
      "expected": "Each MCU's VCAP pins should have the capacitor connections required by its datasheet and should not be used as external signal nets. For the FCC, NET0019 and NET0036 should instead be driven by the MCU's UART GPIO pins.",
      "evidence": [
        {
          "source": "schematic",
          "quote": "VCAP pin 48 = NET0019; VCAP pin 73 = NET0036 (FCC sheet, page 2)"
        },
        {
          "source": "schematic",
          "quote": "UART3_FCC2 connector pins 3 and 4 = NET0019 and NET0036 (FCC Peripherals sheet, page 5)"
        },
        {
          "source": "schematic",
          "quote": "VCAP_1 pin 31 = NET0124; VCAP_2 pin 47 = NET0170; no capacitors are shown on these nets (NAVC sheet, page 3)"
        },
        {
          "source": "schematic",
          "quote": "I2C3_NAVC2 connector pin 4 = NET0124 (NAVC Peripherals sheet, page 6)"
        },
        {
          "source": "spec",
          "quote": "FCC1: STM32H753VITx; NAVC1: STM32F405RGTx (Component Table, Hades)"
        }
      ],
      "impact": "The FCC UART connector is tied to the MCU's VCAP regulator pins rather than UART GPIOs; connecting external equipment could load or disturb the internal core supply, and the UART will not operate as intended. Missing VCAP capacitors can also prevent reliable MCU operation. The NAVC VCAP nets are likewise not decoupled as required.",
      "confidence": 0.99
    }
  ],
  "summary": "The MCU VCAP pins are incorrectly assigned to signal nets, including the FCC UART connector, and the required VCAP capacitors are absent. This can disrupt the MCU core supply and makes the FCC UART interface unusable as drawn."
}

